ALTER TYPE "public"."event_request_status" ADD VALUE 'planning';--> statement-breakpoint
ALTER TYPE "public"."event_request_status" ADD VALUE 'confirmed';--> statement-breakpoint
ALTER TYPE "public"."event_request_status" ADD VALUE 'completed';--> statement-breakpoint
ALTER TYPE "public"."event_request_status" ADD VALUE 'cancelled';--> statement-breakpoint
ALTER TABLE "event_requests" DROP CONSTRAINT "event_requests_decision_matches_status";--> statement-breakpoint
ALTER TABLE "event_requests" ADD CONSTRAINT "event_requests_decision_matches_status" CHECK (("event_requests"."status"::text in ('approved', 'rejected', 'planning', 'confirmed', 'completed') and "event_requests"."decided_by_coordinator_id" is not null and btrim("event_requests"."decided_by_coordinator_id") <> '' and "event_requests"."decided_by_coordinator_name" is not null and btrim("event_requests"."decided_by_coordinator_name") <> '' and "event_requests"."decided_at" is not null) or ("event_requests"."status"::text in ('draft', 'submitted', 'under_review', 'awaiting_organiser') and "event_requests"."decision_reason" is null and "event_requests"."decided_by_coordinator_id" is null and "event_requests"."decided_by_coordinator_name" is null and "event_requests"."decided_at" is null) or ("event_requests"."status"::text = 'cancelled' and (("event_requests"."decided_by_coordinator_id" is not null and btrim("event_requests"."decided_by_coordinator_id") <> '' and "event_requests"."decided_by_coordinator_name" is not null and btrim("event_requests"."decided_by_coordinator_name") <> '' and "event_requests"."decided_at" is not null) or ("event_requests"."decision_reason" is null and "event_requests"."decided_by_coordinator_id" is null and "event_requests"."decided_by_coordinator_name" is null and "event_requests"."decided_at" is null))));